// Energy today: a bar chart drawn as JSX SVG, inside a UI with the totals.
const hours = [0.3, 0.2, 0.2, 0.2, 0.3, 0.4, 0.9, 1.6, 1.2, 0.8, 0.6, 0.5, 0.7, 0.6, 0.9, 0.5]
const solar = [0, 0, 0, 0, 0, 0, 0.1, 0.4, 0.9, 1.5, 2.1, 2.6, 2.8, 2.7, 2.3, 1.8]

const Chart = () => {
  const W = 480, H = 220, max = 3, bw = W / hours.length
  return (
    <svg className="w-full flex-1" viewBox={`0 0 ${W} ${H + 24}`} preserveAspectRatio="none">
      {[1, 2, 3].map((v) => <line x1={0} x2={W} y1={H - (v / max) * H} y2={H - (v / max) * H} stroke="#e7e5e4" strokeWidth={1} />)}
      {solar.map((v, i) => <rect x={i * bw + 3} y={H - (v / max) * H} width={bw - 6} height={(v / max) * H} rx={3} fill="#fcd34d" />)}
      {hours.map((v, i) => <rect x={i * bw + 9} y={H - (v / max) * H} width={bw - 18} height={(v / max) * H} rx={2} fill="#0f766e" />)}
      {[0, 4, 8, 12].map((h) => <text x={h * bw + 2} y={H + 18} fontSize={13} fill="#78716c">{`${String(h).padStart(2, '0')}:00`}</text>)}
    </svg>
  )
}

const Total = ({ label, value, unit, dot }) => (
  <div className="flex flex-col gap-1">
    <div className="flex items-center gap-2">
      <div className={`w-3 h-3 rounded-sm ${dot}`} />
      <span className="text-sm uppercase text-stone-500">{label}</span>
    </div>
    <span className="text-4xl font-bold text-stone-800">{value}<span className="text-xl font-normal text-stone-400">{` ${unit}`}</span></span>
  </div>
)

export function get(app) {
  return (
    <div className="flex gap-6 p-6 bg-stone-100">
      <div className="flex flex-col justify-between w-56">
        <div className="flex flex-col">
          <span className="text-3xl font-bold text-stone-800">Energy</span>
          <span className="text-stone-500">Today until 15:00</span>
        </div>
        <Total label="Used" value="10.3" unit="kWh" dot="bg-teal-700" />
        <Total label="Solar" value="17.2" unit="kWh" dot="bg-amber-300" />
        <div className="rounded-lg bg-emerald-100 text-emerald-800 px-3 py-2 text-sm font-medium">{`6.9 kWh to the grid, €0.48 earned`}</div>
      </div>
      <div className="flex-1 flex flex-col rounded-2xl bg-white p-4 gap-2">
        <span className="text-sm uppercase text-stone-500">kWh per hour</span>
        <Chart />
      </div>
    </div>
  )
}
